import { CheckoutService } from './src/checkout.js';

async function concurrent() {
  let creates = 0;
  let release;
  const gate = new Promise((r) => { release = r; });
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      await gate;
      return { id: 'order-' + creates, cart };
    },
  });
  const p1 = service.placeOrder('k', { sku: 1 });
  const p2 = service.placeOrder('k', { sku: 1 });
  await new Promise((r) => setImmediate(r));
  release();
  const [a, b] = await Promise.all([p1, p2]);
  console.log('CONCURRENT creates', creates, 'sameId', a.id === b.id, 'ids', a.id, b.id);
}

async function conflict() {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'order-' + creates, cart };
    },
  });
  await service.placeOrder('k', { sku: 1 });
  try {
    await service.placeOrder('k', { sku: 2 });
    console.log('CONFLICT no throw, creates', creates);
  } catch (e) {
    console.log('CONFLICT threw', e && e.code, e && e.message, 'creates', creates);
  }
}

await concurrent();
await conflict();
"

