import assert from 'node:assert/strict';
import { CheckoutService } from './src/checkout.js';

function makeService(createImpl) {
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      return createImpl(cart, () => ++creates, () => creates);
    },
  });
  return { service, getCreates: () => creates };
}

// A1 sequential retry
{
  const { service, getCreates } = makeService(async (cart, inc) => ({ id: 'order-' + inc(), cart }));
  const first = await service.placeOrder('checkout-1', { sku: 2 });
  const retry = await service.placeOrder('checkout-1', { sku: 2 });
  assert.deepEqual(retry, first);
  assert.equal(getCreates(), 1);
  console.log('A1 PASS', { id: first.id, creates: getCreates() });
}

// A2 concurrent coalesce
{
  let release;
  const gate = new Promise((r) => { release = r; });
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      const n = ++creates;
      await gate;
      return { id: 'order-' + n, cart };
    },
  });
  const p1 = service.placeOrder('k', { sku: 1 });
  const p2 = service.placeOrder('k', { sku: 1 });
  await new Promise((r) => setImmediate(r));
  release();
  const [a, b] = await Promise.all([p1, p2]);
  assert.equal(creates, 1);
  assert.deepEqual(a, b);
  assert.equal(a.id, 'order-1');
  console.log('A2 PASS', { creates, a, b, sameRef: a === b });
}

// A3 conflict after complete
{
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      return { id: 'order-' + creates, cart };
    },
  });
  const first = await service.placeOrder('k', { sku: 1 });
  let err = null;
  try {
    await service.placeOrder('k', { sku: 2 });
