    async create(cart) {
      creates += 1;
      await gate;
      return { id: 'order-' + creates, cart };
    },
  });
  const p1 = service.placeOrder('k', { sku: 1 });
  await new Promise((r) => setImmediate(r));
  let err = null;
  try {
    await service.placeOrder('k', { sku: 2 });
  } catch (e) {
    err = e;
  }
  release();
  const first = await p1;
  assert.ok(err);
  assert.equal(err.code, 'IDEMPOTENCY_CONFLICT');
  assert.equal(creates, 1);
  assert.equal(first.id, 'order-1');
  console.log('A3b PASS', { code: err.code, creates });
}

// A4 failed creation does not poison
{
  let creates = 0;
  const service = new CheckoutService({
    async create(cart) {
      creates += 1;
      if (creates === 1) throw new Error('database unavailable');
      return { id: 'recovered', cart };
    },
  });
  await assert.rejects(service.placeOrder('checkout-2', { sku: 1 }), /database unavailable/);
  const recovered = await service.placeOrder('checkout-2', { sku: 1 });
  assert.equal(recovered.id, 'recovered');
  assert.equal(creates, 2);
  console.log('A4 PASS', { id: recovered.id, creates });
}

// A4b concurrent shared failure then later retry
{
  let release;
  const gate = new Promise((r) => { release = r; });
